int main() {
    int N, K;
    scanf("%d %d", &N, &K);

    int *A = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) {
        scanf("%d", &A[i]);
    }

    // reply_count[i] = how many replies tweet i has received
    int *reply_count = (int*)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) {
        if (A[i] > 0) {
            reply_count[A[i]]++;
        }
    }

    int *displayed = (int*)calloc(N + 1, sizeof(int));

    // First pass: tweets that are roots (A_i == 0) and have no replies are displayed
    for (int i = 1; i <= N; i++) {
        if (A[i] == 0 && reply_count[i] == 0) {
            displayed[i] = 1;
        }
    }

    // For tweets that have no replies (reply_count[i] == 0) but are not roots,
    // we need to check if we can trace back within K replies to a tweet with no replies.
    // We'll use a simple approach: for each tweet with reply_count[i] == 0 and A[i] > 0,
    // walk up the reply chain up to K steps and check if we encounter a tweet that has no replies.
    // Actually condition says: "If it comes from a tweet that meets condition 2, it can be traced back within K replies."
    // This means: a tweet is displayed if there exists some ancestor (including itself) within K steps up
    // that has no replies (reply_count == 0).

    // Let's do it for all tweets that have reply_count[i] == 0 but are not yet marked.
    for (int i = 1; i <= N; i++) {
        if (reply_count[i] == 0 && !displayed[i]) {
            // walk up
            int cur = i;
            int steps = 0;
            int found = 0;
            while (cur > 0 && steps <= K) {
                if (A[cur] == 0) {
                    // This is a root. It has no replies? Actually if it's a root, it has no parent.
                    // But we already handled roots with reply_count==0.
                    // If we reach a root, it means the chain ends. 
                    // The root itself: if reply_count[root]==0, it's displayed; otherwise not.
                    // But we are walking from a leaf (reply_count==0). If we reach a root,
                    // the root's reply_count might be >0. In that case, the leaf is not displayed
                    // because the root has replies. But wait: condition says "If it comes from a tweet that meets condition 2"
                    // i.e., the ancestor must have no replies. So if the root has replies, it fails.
                    if (reply_count[cur] == 0) {
                        found = 1;
                    }
                    break;
                }
                // Check if current node has no replies
                if (reply_count[cur] == 0) {
                    found = 1;
                    break;
                }
                cur = A[cur];
                steps++;
            }
            if (found) {
                displayed[i] = 1;
            }
        }
    }

    // Also need to consider tweets that have replies but might be displayed?
    // Condition 1: has not replied to any tweet (A_i == 0). Already handled.
    // Condition 2: has not received any replies (reply_count[i] == 0). Already handled.
    // Condition 3: can be traced back within K replies to a tweet that meets condition 2.
    // So only tweets with reply_count[i] == 0 can be the "source" for condition 3.
    // But what about a tweet that has replies? It can only be displayed if it itself has no replies (condition 2)
    // or is a root (condition 1). So tweets with reply_count > 0 cannot be displayed unless they are roots.
    // Actually if a tweet has replies, condition 2 fails. Condition 1: only if A_i == 0 (root).
    // So a non-root with replies is never displayed.

    // Count displayed
    int ans = 0;
    for (int i = 1; i <= N; i++) {
        if (displayed[i]) ans++;
    }

    printf("%d\n", ans);

    free(A);
    free(reply_count);
    free(displayed);

    return 0;
}

