int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *A = (int *)malloc((N + 1) * sizeof(int));
    int *childCount = (int *)calloc(N + 1, sizeof(int));
    int *depth = (int *)malloc((N + 1) * sizeof(int));

    for (int i = 1; i <= N; i++) {
        scanf("%d", &A[i]);
        if (A[i] > 0) childCount[A[i]]++;
    }

    long long ans = 0;

    for (int i = 1; i <= N; i++) {
        if (A[i] == 0) {
            depth[i] = 0;
            ans++;                    // Condition 1
        } else if (childCount[i] == 0) {
            depth[i] = 0;
            ans++;                    // Condition 2
        } else {
            depth[i] = depth[A[i]] + 1;
            if (depth[i] <= K) ans++; // Condition 3
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(childCount);
    free(depth);
    return 0;
}

