    cin >> N >> K;

    vector<int> A(N + 1); // 1-indexed
    for (int i = 1; i <= N; i++) {
        cin >> A[i];
    }

    // indegree[i] = number of direct replies to tweet i
    vector<int> indegree(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        if (A[i] != 0) {
            indegree[A[i]]++;
        }
    }

    // displayable[i] = true if tweet i is displayed
    vector<bool> displayable(N + 1, false);

    // First pass: condition 1 (no reply to any tweet) and condition 2 (no replies received)
    for (int i = 1; i <= N; i++) {
        if (A[i] == 0) {
            displayable[i] = true; // condition 1
        }
        if (indegree[i] == 0) {
            displayable[i] = true; // condition 2
        }
    }

    // For condition 3: BFS/DFS from roots (tweets with indegree 0) and propagate up to K depth
    // We'll use a queue for BFS, storing (tweet_id, depth)
    vector<vector<int>> children(N + 1);
    for (int i = 1; i <= N; i++) {
        if (A[i] != 0) {
            children[A[i]].push_back(i);
        }
    }

    queue<pair<int, int>> q;
    // Start from tweets that are roots (indegree 0) and already displayable by condition 2
    for (int i = 1; i <= N; i++) {
        if (indegree[i] == 0) {
            q.push({i, 0});
        }
    }

    while (!q.empty()) {
        auto [u, depth] = q.front();
        q.pop();
        if (depth > 0) {
            displayable[u] = true; // reachable within K from a root
        }
        if (depth < K) {
            for (int v : children[u]) {
                q.push({v, depth + 1});
            }
        }
    }

    int ans = 0;
    for (int i = 1; i <= N; i++) {
        if (displayable[i]) ans++;
    }
    cout << ans << "\n";

    return 0;
}

