        }
    }

    // Compute min distance to leaf for each node
    vector<int> min_dist(N+1, INT_MAX);

    // Process in topological order (leaves first)
    // Use post-order traversal
    // Find roots
    vector<int> roots;
    for(int i = 1; i <= N; i++){
        if(A[i] == 0) roots.push_back(i);
    }

    // Iterative post-order
    vector<bool> visited(N+1, false);
    stack<pair<int,bool>> st;
    for(int r : roots) st.push({r, false});

    while(!st.empty()){
        auto [node, processed] = st.top();
        st.pop();
        if(processed){
            if(children[node].empty()){
                min_dist[node] = 0;
            } else {
                int mn = INT_MAX;
                for(int c : children[node]){
                    if(min_dist[c] != INT_MAX)
                        mn = min(mn, min_dist[c] + 1);
                }
                min_dist[node] = mn;
            }
        } else {
            st.push({node, true});
            for(int c : children[node]){
                st.push({c, false});
            }
        }
    }

    int count = 0;
    for(int i = 1; i <= N; i++){
        if(A[i] == 0 || min_dist[i] <= K){
            count++;
        }
