            dist[p] = dist[v] + 1;
            q.push(p);
        }
    }

    int ans = 0;
    for (int i = 1; i <= N; i++) {
        // condition 1: not replying to any tweet
        // condition 3 includes condition 2 as dist[i] = 0
        if (A[i] == 0 || dist[i] != -1) ans++;
    }

    cout << ans << '\n';
    return 0;
