    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int K = fs.nextInt();

        int[] parent = new int[N + 1];
        int[] childCount = new int[N + 1];

        for (int i = 1; i <= N; i++) {
            parent[i] = fs.nextInt();
            if (parent[i] != 0) childCount[parent[i]]++;
        }

        boolean[] visible = new boolean[N + 1];

        // Condition 1: tweets that do not reply to any tweet
        for (int i = 1; i <= N; i++) {
            if (parent[i] == 0) visible[i] = true;
        }

        // Condition 2 and 3:
        // From every leaf tweet (no replies), trace back up to K replies.
        for (int i = 1; i <= N; i++) {
            if (childCount[i] == 0) {
                int cur = i;
                int steps = 0;
                while (cur != 0 && steps <= K) {
                    visible[cur] = true;
                    cur = parent[cur];
                    steps++;
                }
            }
        }

        int ans = 0;
        for (int i = 1; i <= N; i++) {
            if (visible[i]) ans++;
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

