from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    T = int(input_data[idx]); idx += 1
    for _ in range(T):
        N, K = int(input_data[idx]), int(input_data[idx+1]); idx += 2
        A = []
        for i in range(N):
            A.append(int(input_data[idx])); idx += 1

        children = defaultdict(list)
        is_root = []
        for i in range(N):
            if A[i] == 0:
                is_root.append(True)
            else:
                is_root.append(False)
                children[A[i]-1].append(i)  # 0-indexed

        # Find leaves
        is_leaf = [len(children[i]) == 0 for i in range(N)]

        # Compute min distance to leaf descendant for each node
        # Use post-order DFS
        min_dist = [float('inf')] * N

        # Topological order (process children before parents)
        # Since it's a forest, we can do DFS
        visited = [False] * N

        def dfs(node):
            visited[node] = True
            if is_leaf[node]:
                min_dist[node] = 0
            else:
                for child in children[node]:
                    if not visited[child]:
                        dfs(child)
                    min_dist[node] = min(min_dist[node], min_dist[child] + 1)

        sys.setrecursionlimit(300000)
        for i in range(N):
            if is_root[i] and not visited[i]:
                dfs(i)

        count = 0
        for i in range(N):
            if is_root[i] or is_leaf[i] or min_dist[i] <= K:
                count += 1

        print(count)

