    A = list(map(int, input().split()))

    # outdeg[i]: number of replies to tweet i (1-indexed)
    outdeg = [0] * (N + 1)
    for i, p in enumerate(A, start=1):
        if p != 0:
            outdeg[p] += 1

    ans = 0

    # 1) Tweets that do not reply to any tweet
    for i in range(1, N + 1):
        if A[i - 1] == 0:
            ans += 1

    # 2) Tweets that have no replies
    # 3) Ancestors within K replies from such tweets
    for leaf in range(1, N + 1):
        if outdeg[leaf] == 0:
            cur = leaf
            steps = 0
            while cur != 0 and steps <= K:
                # Count this tweet if it is not already counted by condition 1
                if A[cur - 1] != 0:
                    ans += 1
                cur = A[cur - 1]
                steps += 1

    print(ans)

